<?php defined('ABSPATH') || exit;$base=home_url('/companion/');$root='dungeon-master/campaigns/'.$campaign->id().'/evidence';$threadMap=[];foreach(($threads??[]) as $item){$threadMap[$item->id()]=$item;}$locationMap=[];foreach(($locations??[]) as $item){$locationMap[$item->id()]=$item;}$personaMap=[];foreach(($personae??[]) as $item){$personaMap[$item->id()]=$item;} ?>
<section class="gmrc-evidence"><header class="gmrc-evidence__hero"><div><p class="gmrc-dm-desk__eyebrow"><?php echo esc_html($record->typeLabel()); ?> · <?php echo $record->isKeeperOnly()?'Keeper only':'Player-visible'; ?><?php echo $record->isArchived()?' · Archived':''; ?></p><h1><?php echo esc_html($record->name()); ?></h1></div><?php if(!$campaign->isArchived()&&!$record->isArchived()): ?><a class="gmrc-evidence-button" href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$record->id().'/edit',$base)); ?>">Edit Record</a><?php endif; ?></header>
<article class="gmrc-evidence-page"><section><h2>At a glance</h2><p><?php echo $record->summary()!==''?esc_html($record->summary()):'No summary has been written yet.'; ?></p></section><section><h2>Keeper’s notes</h2><div><?php echo $record->notes()!==''?wpautop(esc_html($record->notes())):'<p>No private notes have been written yet.</p>'; ?></div></section>
<?php if(!$record->isThread()&&$record->threadIds()!==[]): ?><section><h2>Threads</h2><ul><?php foreach($record->threadIds() as $id): if(!isset($threadMap[$id])){continue;} ?><li><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$id,$base)); ?>"><?php echo esc_html($threadMap[$id]->name()); ?></a></li><?php endforeach; ?></ul></section><?php endif; ?>
<?php if($record->locationIds()!==[]): ?><section><h2>Locations</h2><ul><?php foreach($record->locationIds() as $id): if(!isset($locationMap[$id])){continue;} ?><li><?php echo esc_html($locationMap[$id]->name()); ?></li><?php endforeach; ?></ul></section><?php endif; ?><?php if($record->personaIds()!==[]): ?><section><h2>People & factions</h2><ul><?php foreach($record->personaIds() as $id): if(!isset($personaMap[$id])){continue;} ?><li><?php echo esc_html($personaMap[$id]->name()); ?> · <?php echo esc_html($personaMap[$id]->kindLabel()); ?></li><?php endforeach; ?></ul></section><?php endif; ?><section class="gmrc-evidence-page__board"><h2>Conspiracy Board</h2><p>This stable campaign record and its relationships are ready to become future pins and strings without duplicating their source data.</p></section></article>
<?php if($record->isThread()&&($linkedEvidence??[])!==[]): ?><section class="gmrc-evidence-linked"><h2>Evidence attached to this thread</h2><div class="gmrc-evidence-grid"><?php foreach($linkedEvidence as $linked): ?><article class="gmrc-evidence-card"><h3><?php echo esc_html($linked->name()); ?></h3><p><?php echo esc_html($linked->typeLabel()); ?></p><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root.'/'.$linked->id(),$base)); ?>">Open evidence →</a></article><?php endforeach; ?></div></section><?php endif; ?>
<?php if(!$campaign->isArchived()&&!$record->isArchived()): ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="gmrc-evidence-archive-form" onsubmit="return confirm('Archive this Evidence Register record?');"><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="<?php echo esc_attr($root.'/'.$record->id().'/archive'); ?>"><input type="hidden" name="_method" value="POST"><input type="hidden" name="gmrc_nonce" value="<?php echo esc_attr(wp_create_nonce('gmrc_dm_evidence_'.$campaign->id())); ?>"><button type="submit">Archive record</button></form><?php endif; ?><p class="gmrc-evidence-back"><a href="<?php echo esc_url(add_query_arg('gmrc_route',$root,$base)); ?>">← Back to Evidence Register</a></p></section>
